package com.nexodb.ui;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.util.*;
import java.util.List;
import static com.nexodb.util.I18n.tr;

/** Searchable, offline product manual. */
final class HelpManualPanel extends JPanel {
    private record Topic(String group,String title,String summary,String steps,String tip) {public String search(){return (group+" "+title+" "+summary+" "+steps+" "+tip).toLowerCase(Locale.ROOT);}}
    private final List<Topic> all=topics();private final DefaultListModel<Topic> model=new DefaultListModel<>();private final JList<Topic> index=new JList<>(model);private final JEditorPane page=new JEditorPane("text/html","");private final JTextField search=new JTextField();private final Illustration illustration=new Illustration();
    HelpManualPanel(){super(new BorderLayout(8,8));setName("help-manual");setBorder(new EmptyBorder(10,10,10,10));JPanel top=new JPanel(new BorderLayout(8,0));top.add(new JLabel(tr("Buscar en el manual:")),BorderLayout.WEST);UiLanguage.placeholder(search,"Ej.: exportar, SSH, relaciones, monitor");top.add(search);add(top,BorderLayout.NORTH);index.setName("manual-index");index.setCellRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?> list,Object value,int i,boolean selected,boolean focus){Topic topic=(Topic)value;return super.getListCellRendererComponent(list,"  "+topic.group()+"  ›  "+topic.title(),i,selected,focus);}});page.setEditable(false);page.putClientProperty(JEditorPane.HONOR_DISPLAY_PROPERTIES,Boolean.TRUE);JPanel article=new JPanel(new BorderLayout());article.add(illustration,BorderLayout.NORTH);article.add(new JScrollPane(page));JSplitPane split=new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,new JScrollPane(index),article);split.setDividerLocation(310);split.setResizeWeight(0);add(split);search.getDocument().addDocumentListener(new javax.swing.event.DocumentListener(){private void changed(){filter();}public void insertUpdate(javax.swing.event.DocumentEvent e){changed();}public void removeUpdate(javax.swing.event.DocumentEvent e){changed();}public void changedUpdate(javax.swing.event.DocumentEvent e){changed();}});index.addListSelectionListener(e->{if(!e.getValueIsAdjusting())showTopic(index.getSelectedValue());});filter();}
    private void filter(){String value=search.getText().trim().toLowerCase(Locale.ROOT);Topic selected=index.getSelectedValue();model.clear();for(Topic topic:all)if(value.isBlank()||topic.search().contains(value))model.addElement(topic);if(selected!=null&&model.contains(selected))index.setSelectedValue(selected,true);else if(!model.isEmpty())index.setSelectedIndex(0);}
    private void showTopic(Topic topic){if(topic==null){page.setText("<html><h2>"+tr("Sin resultados")+"</h2><p>"+tr("Prueba con otra palabra.")+"</p></html>");return;}illustration.topic=topic;illustration.repaint();page.setText("<html><body style='font-family:sans-serif;margin:18px'><h1>"+escape(topic.title())+"</h1><p style='font-size:12pt'>"+topic.summary()+"</p><h2>"+tr("Cómo se hace")+"</h2><ol>"+Arrays.stream(topic.steps().split("\\|",-1)).map(step->"<li style='margin-bottom:8px'>"+step+"</li>").reduce("",String::concat)+"</ol><hr><p><b>💡 "+tr("Consejo")+":</b> "+topic.tip()+"</p></body></html>");page.setCaretPosition(0);}
    private static String escape(String text){return text.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}
    private static List<Topic> topics(){return List.of(
        new Topic("Primeros pasos","Conectar una base de datos","Crea perfiles para MySQL, MariaDB, PostgreSQL, SQL Server, Oracle, SQLite, H2, MongoDB o JDBC genérico.","Pulsa <b>Nueva conexión</b>.|Elige el motor y completa host, puerto, usuario y base opcional.|Usa <b>Verificar / descargar driver</b> si el controlador falta.|Pulsa <b>Probar</b> y después <b>Guardar y conectar</b>.","Activa Solo lectura para servidores productivos. Las claves recordadas se cifran con el sistema operativo."),
        new Topic("Conexiones","Túnel SSH y seguridad","Conecta a bases no expuestas directamente usando un servidor SSH.","Abre la configuración avanzada de la conexión.|Activa <b>SSH</b> e indica host, puerto, usuario y autenticación.|Indica el host de la base desde la perspectiva del servidor remoto.|Prueba la conexión antes de guardarla.","Usa claves SSH protegidas y limita permisos del usuario de base de datos."),
        new Topic("Consultas","Editor SQL y autocompletado","Escribe SQL con coloreado, palabras reservadas, alias, tablas y columnas sugeridas.","Selecciona la conexión y la base.|Escribe la consulta; usa el prefijo o alias seguido de punto para ver sus columnas.|Selecciona texto para ejecutar solo esa parte o coloca el cursor en una sentencia.|Pulsa F5 o Ejecutar; Esc cancela.","Mantén Limitar filas activado mientras exploras tablas grandes."),
        new Topic("Resultados","Editar, insertar y guardar filas","Edita resultados seguros, crea filas nuevas y usa valores DEFAULT o NULL.","Selecciona una tabla editable en el selector del resultado.|Pulsa Editar o elige la tabla de origen si hay JOIN.|Cambia una celda; al pasar de fila se guarda la anterior.|Usa la fila nueva al final para insertar y deja el ID autonumérico como DEFAULT.","La edición exige una clave que identifique cada fila; incluye la clave primaria en el SELECT."),
        new Topic("Resultados","Filtros, orden y páginas","Filtra por columna, combina condiciones y navega con paginación por clave.","Pulsa el embudo del encabezado.|Elige valor, NULL, condición personalizada u orden ascendente/descendente.|Aplica el filtro; se ejecuta en el servidor.|Usa las flechas, primera/última página o escribe una página concreta.","El conteo total puede ejecutarse en segundo plano y cancelarse si resulta costoso."),
        new Topic("Resultados","Campos largos, fechas, ENUM y relaciones","Edita texto/XML/JSON en una ventana amplia, fechas con calendario y referencias visuales.","Haz doble clic en una celda larga para abrir el editor.|Usa Formatear solo para visualizar; el original se conserva si no aceptas cambios.|En fechas usa el calendario y la hora.|En una clave foránea abre la referencia para buscar o elegir el registro relacionado.","Ctrl+C y Ctrl+V funcionan en celdas cuando el resultado está en modo escritura."),
        new Topic("Exportación","Exportar resultados grandes","Exporta CSV, Excel, JSON, XML, SQL, HTML y otros formatos sin cargar todo en memoria.","Ejecuta la consulta.|Pulsa Exportar y elige formato y archivo.|Confirma exportar el resultado completo.|Consulta progreso o cancela desde Operaciones en segundo plano.","La exportación usa una conexión auxiliar para no bloquear el editor."),
        new Topic("Estructura","Crear y modificar tablas","Diseña columnas con tipos propios del motor, claves, autoincremento, valores predeterminados, collation y ENUM.","Abre el Diseñador de esquemas o la estructura de una tabla.|Agrega columnas y selecciona tipo y propiedades.|Define índices y claves foráneas en sus pestañas.|Revisa la Vista previa SQL y guarda los cambios.","Si el servidor rechaza el cambio, el formulario conserva lo escrito para corregirlo."),
        new Topic("Estructura","Índices y relaciones","Crea, edita y elimina índices o claves foráneas de forma visual.","Abre la tabla y entra en Índices o Claves foráneas.|Pulsa Nuevo o Modificar.|Elige columnas, tabla referenciada y acciones ON DELETE/ON UPDATE.|Revisa y aplica el SQL.","La columna referenciada necesita un índice compatible y tipos equivalentes."),
        new Topic("Herramientas","Comparar y copiar datos","Compara instancias, bases y tablas o copia tablas entre conexiones.","Abre Comparación y elige conexión y base de origen/destino.|Selecciona todas las tablas o solo algunas.|Ejecuta la comparación y revisa el script.|Para copiar, usa el menú de la tabla y elige la conexión destino.","Compara de nuevo después de un error para transferir solo lo que falta."),
        new Topic("Reportería","Diseñar, actualizar e imprimir reportes","Crea reportes fieles a la vista previa, con orientación, agrupaciones, totales y gráficos.","Abre Reportería y selecciona un resultado.|Pulsa Usar resultado.|Configura columnas, objetos, orientación y página.|Actualiza, exporta PDF/HTML/Excel o imprime.","Actualizar lista vuelve a ejecutar el origen cuando esté disponible; revisa el resultado antes de imprimir."),
        new Topic("Administración","Usuarios y permisos","Consulta permisos efectivos y concede o revoca solo en el ámbito que los originó.","Abre Administrar usuarios desde Base de datos.|Selecciona usuario y host.|Usa Ver permisos para revisar GRANT globales y por base.|En Permisos marca o desmarca privilegios y confirma.","Un permiso heredado de *.* debe retirarse en el ámbito global; se necesita GRANT OPTION o privilegios administrativos."),
        new Topic("Administración","Monitor de sesiones y bloqueos","Ve consultas activas, bloqueos, transacciones y saturación sin detener la interfaz.","Abre Herramientas avanzadas › Monitor del servidor.|Activa actualización automática y define intervalo.|Selecciona una sesión para ver estado, duración y bloqueo.|Con permisos suficientes puedes cancelar la consulta o cerrar la sesión tras confirmar.","El SQL está oculto por defecto. Sin permisos administrativos el monitor funciona en modo informativo."),
        new Topic("Rendimiento","Diagnóstico y operaciones en segundo plano","Distingue tiempo de servidor, transferencia, metadatos e interfaz; controla tareas y límites.","Revisa el tiempo y el icono Diagnóstico bajo el resultado.|Abre Operaciones en segundo plano para ver consultas, conteos, exportaciones y precargas.|Cancela o reintenta una tarea.|Activa Ajuste adaptativo para regular concurrencia según memoria y errores.","Usa Plan de ejecución cuando el servidor concentre la mayor parte del tiempo."),
        new Topic("IA","Generar SQL con lenguaje natural","Describe lo que necesitas y genera una propuesta según el esquema de la base seleccionada.","Configura proveedor, modelo, endpoint y clave.|Selecciona la base y actualiza el contexto de tablas.|Escribe la petición en lenguaje natural.|Genera la propuesta, revísala y ábrela en una consulta nueva.","La propuesta nunca se ejecuta automáticamente; revisa filtros y sentencias de escritura."),
        new Topic("Seguridad","Auditoría y recuperación","Registra operaciones administrativas sin datos sensibles y recupera borradores tras un cierre inesperado.","Abre Auditoría local para revisar acciones, estado y huellas irreversibles.|Tras un cierre inesperado, abre Recuperación para ver tareas interrumpidas.|Revisa los borradores restaurados.|Vuelve a ejecutar únicamente lo necesario.","No se guardan resultados, SQL en auditoría, parámetros, credenciales ni contenido de celdas."),
        new Topic("Actualizaciones","Actualizar AdisDB","Descarga e instala nuevas versiones desde el propio programa.","Abre Ayuda › Buscar actualizaciones.|Revisa versión y notas.|Descarga e instala.|Cierra cuando se solicite; el instalador reemplaza la versión y reinicia.","Si vuelve a ofrecer la misma versión, verifica que se abrió el ejecutable instalado y no una copia anterior.")
    );}
    private static final class Illustration extends JComponent {Topic topic;Illustration(){setPreferredSize(new Dimension(100,112));}protected void paintComponent(Graphics graphics){super.paintComponent(graphics);Graphics2D g=(Graphics2D)graphics.create();g.setRenderingHint(RenderingHints.KEY_ANTIALIASING,RenderingHints.VALUE_ANTIALIAS_ON);int w=getWidth(),y=28;g.setColor(new Color(20,126,113));g.fillRoundRect(20,y,170,55,16,16);g.fillRoundRect(w/2-85,y,170,55,16,16);g.fillRoundRect(w-190,y,170,55,16,16);g.setColor(new Color(255,255,255));g.setFont(g.getFont().deriveFont(Font.BOLD,13f));center(g,topic==null?"Índice":topic.group(),20,y,170,55);center(g,topic==null?"Seleccionar":topic.title(),w/2-85,y,170,55);center(g,"Resultado seguro",w-190,y,170,55);g.setColor(new Color(20,126,113));g.setStroke(new BasicStroke(3));g.drawLine(190,y+27,w/2-85,y+27);g.drawLine(w/2+85,y+27,w-190,y+27);g.dispose();}private static void center(Graphics2D g,String text,int x,int y,int w,int h){String value=text.length()>22?text.substring(0,20)+"…":text;FontMetrics fm=g.getFontMetrics();g.drawString(value,x+(w-fm.stringWidth(value))/2,y+(h+fm.getAscent())/2-3);}}
}
